// Pyodide runner of the `wasm` Python backend (Python spec §8.2). Plain JavaScript on purpose: it
// runs in a child `node` started with --permission, outside the Alisio bundle, and ships inside
// `pyodide-runner-source.ts` (generated by scripts/pyodide-runner-source.ts) because the npm
// package and the standalone binary carry no loose files.
//
// argv[2] is one JSON object: { dist, wheelsDir?, packages, wheels, job: { script, input, work,
// out, scratch? } }. Environment: ALISIO_EXECUTION_ID, ALISIO_FORGE_NONCE, ALISIO_FORGE_ENGINE.
// Exit code: the script's own (0 = ok, 1 = it raised), 70 when the runner itself failed.
// The runner holds no secret: Python reaches this JavaScript through the FFI (verified in P0), so
// everything it can do is bounded by the Permission Model flags the parent chose.
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

const spec = JSON.parse(process.argv[2] ?? "{}");
const SCRATCH_CAP_BYTES = 64 * 1024 * 1024;
const started = performance.now();

// 1. No network entry points for the script. Not a boundary (node:http is still reachable through
//    the FFI on Node 22/24); it only closes the obvious doors and keeps Pyodide on node:fs.
for (const name of ["fetch", "WebSocket", "XMLHttpRequest", "EventSource", "navigator"]) {
  try {
    delete globalThis[name];
  } catch {
    /* non-configurable in this runtime */
  }
}

// 2. Emscripten's NODEFS calls process.binding("constants"), which --permission denies.
if (process.permission) {
  process.binding = (name) => {
    if (name === "constants") return { fs: fs.constants };
    throw new Error(`process.binding(${name}) is disabled`);
  };
}

// 3. process.kill could end the parent or any process of the user; replaced and frozen (D-32).
//    A mitigation, not a boundary: the OS still lets the child signal its own group.
const denied = () => {
  throw new Error("process.kill is disabled in the Alisio wasm runner");
};
for (const name of ["kill", "_kill"]) {
  try {
    Object.defineProperty(process, name, {
      value: denied,
      writable: false,
      configurable: false,
      enumerable: true,
    });
  } catch {
    /* already frozen */
  }
}

// What the runner reports reaches the model: host absolute paths never do. The folders it was
// given become placeholders; any other absolute path keeps only its last segment.
const KNOWN_PATHS = [
  [spec.dist, "<dist>"],
  [spec.job?.script, "<job>/script"],
  [spec.job?.input, "<job>/input"],
  [spec.job?.work, "<job>/work"],
  [spec.job?.out, "<job>/out"],
  [spec.job?.scratch, "<job>/scratch"],
]
  .filter(([host]) => typeof host === "string" && host.length > 1)
  .sort((a, b) => b[0].length - a[0].length);
const redact = (text) => {
  let result = String(text);
  for (const [host, label] of KNOWN_PATHS) {
    result = result.split(pathToFileURL(host).href).join(label).split(host).join(label);
  }
  return result.replace(
    /(?<![\w:.<>~-])(?:file:\/\/)?(?:[A-Za-z]:)?[\\/](?:[^\s:()'"\\/]+[\\/])+([^\s:()'"\\/]+)/g,
    "<host>/$1",
  );
};

const fail = (message, code = 70) => {
  process.stderr.write(`alisio wasm runner: ${redact(message)}\n`, () => process.exit(code));
};

// An error thrown into a Node event handler (a Python callback that raised, say) would otherwise
// end the process with Node's report, which quotes the Emscripten source: keep it to one line.
const brief = (error) =>
  redact(String(error instanceof Error ? error.message : error).split("\n")[0]);
process.on("uncaughtException", (error) => fail(`uncaught exception: ${brief(error)}`));
process.on("unhandledRejection", (error) => fail(`unhandled rejection: ${brief(error)}`));

const writeLine = (stream) => (line) => {
  stream.write(`${line}\n`);
};

try {
  const { loadPyodide } = await import(pathToFileURL(path.join(spec.dist, "pyodide.mjs")).href);
  const py = await loadPyodide({
    indexURL: `${spec.dist}/`,
    lockFileURL: path.join(spec.dist, "pyodide-lock.json"),
    packageCacheDir: `${spec.dist}/`,
    env: {
      ALISIO_INPUT_DIR: "/job/input",
      ALISIO_OUTPUT_DIR: "/job/out",
      ALISIO_WORK_DIR: "/job/work",
      ALISIO_EXECUTION_ID: process.env.ALISIO_EXECUTION_ID ?? "",
      ALISIO_FORGE_NONCE: process.env.ALISIO_FORGE_NONCE ?? "",
      ALISIO_FORGE_ENGINE: process.env.ALISIO_FORGE_ENGINE ?? "python-wasm",
      ...(spec.job.scratch ? { ALISIO_SCRATCH_DIR: "/job/scratch" } : {}),
      MPLBACKEND: "Agg",
      HOME: "/job/work",
      TMPDIR: "/job/work",
      PYTHONDONTWRITEBYTECODE: "1",
    },
    stdout: writeLine(process.stdout),
    stderr: writeLine(process.stderr),
  });

  // 4. Only what the script needs: lock packages by name (their dependencies resolve from the
  //    lock), then the pure wheels from the local folder, in the manifest's dependency order.
  const messages = (m) => process.stderr.write(`${m}\n`);
  if (spec.packages.length)
    await py.loadPackage(spec.packages, { messageCallback: () => {}, errorCallback: messages });
  for (const wheel of spec.wheels)
    await py.loadPackage(pathToFileURL(path.join(spec.dist, wheel)).href, {
      messageCallback: () => {},
      errorCallback: messages,
    });

  // 5. The job lives in Pyodide's own file system; only these folders are read from the host.
  const copyIn = (hostDir, vDir, budget) => {
    py.FS.mkdirTree(vDir);
    let used = 0;
    const walk = (host, virtual) => {
      for (const entry of fs.readdirSync(host, { withFileTypes: true })) {
        const from = path.join(host, entry.name);
        const to = `${virtual}/${entry.name}`;
        if (entry.isDirectory()) {
          py.FS.mkdirTree(to);
          walk(from, to);
        } else if (entry.isFile()) {
          const size = fs.statSync(from).size;
          if (budget !== undefined && used + size > budget) continue;
          used += size;
          py.FS.writeFile(to, fs.readFileSync(from));
        }
      }
    };
    walk(hostDir, vDir);
  };
  for (const dir of ["/job", "/job/out"]) py.FS.mkdirTree(dir);
  copyIn(spec.job.script, "/job/script");
  copyIn(spec.job.input, "/job/input");
  copyIn(spec.job.work, "/job/work");
  if (spec.job.scratch) copyIn(spec.job.scratch, "/job/scratch", SCRATCH_CAP_BYTES);
  py.FS.chdir("/job/work");

  // The parent times the start from this file (not from a line, which would end up in the
  // script's output and in the logs). Python can write it too; that only skews a metric.
  fs.mkdirSync(path.join(spec.job.work, ".forge"), { recursive: true });
  fs.writeFileSync(
    path.join(spec.job.work, ".forge", "wasm-ready"),
    String(Math.round(performance.now() - started)),
  );

  // 6. Run main.py as __main__ in a real module (dataclasses and pickling look it up in
  //    sys.modules), with top-level await allowed; the exit code follows the script (SystemExit
  //    included). Pyodide never finalizes the interpreter, so the atexit handlers (Forja's final
  //    value) run here, after the script and also after a failure, as CPython would.
  py.globals.set("_alisio_main", "/job/script/main.py");
  const code = await py.runPythonAsync(`
import atexit, sys, traceback, types
from pyodide.code import eval_code_async

async def _alisio_run(path):
    sys.argv = [path]
    sys.path.insert(0, "/job/script")
    module = types.ModuleType("__main__")
    module.__file__ = path
    sys.modules["__main__"] = module
    try:
        with open(path, encoding="utf-8") as handle:
            source = handle.read()
        await eval_code_async(source, module.__dict__, filename=path, return_mode="none")
        return 0
    except SystemExit as exit_:
        value = exit_.code
        if value is None:
            return 0
        if isinstance(value, int):
            return value & 255
        print(value, file=sys.stderr)
        return 1
    except BaseException as error:
        tb = error.__traceback__
        while tb is not None and tb.tb_frame.f_code.co_filename != path:
            tb = tb.tb_next
        traceback.print_exception(type(error), error, tb if tb is not None else error.__traceback__)
        return 1
    finally:
        try:
            atexit._run_exitfuncs()
            sys.stdout.flush()
            sys.stderr.flush()
        except BaseException:
            traceback.print_exc()

await _alisio_run(_alisio_main)
`);

  // 7. Whatever the script left in /job/out goes to the real out folder (symlinks are not followed).
  const copyOut = (virtual, host) => {
    for (const name of py.FS.readdir(virtual)) {
      if (name === "." || name === "..") continue;
      const from = `${virtual}/${name}`;
      const to = path.join(host, name);
      const info = py.FS.lstat(from);
      if (py.FS.isDir(info.mode)) {
        fs.mkdirSync(to, { recursive: true });
        copyOut(from, to);
      } else if (py.FS.isFile(info.mode)) fs.writeFileSync(to, py.FS.readFile(from));
    }
  };
  copyOut("/job/out", spec.job.out);

  const exitCode = Number(code) | 0;
  process.stdout.write("", () => process.stderr.write("", () => process.exit(exitCode)));
} catch (error) {
  fail(error instanceof Error ? (error.stack ?? error.message) : String(error));
}
